#!/usr/bin/env python3

import argparse
import subprocess
import sys
import tempfile
from itertools import batched
from pathlib import Path
from textwrap import dedent


def bytes_to_c_array(data: bytes, name: str, *, source: Path) -> str:
    hex_bytes = "\n".join(f"  {', '.join(f'0x{b:02x}' for b in chunk)}," for chunk in batched(data, 12))
    return dedent(
        """\
        // Generated by scripts/asm2c.py from {source}.
        // Do not edit by hand; regenerate the header instead.

        #pragma once

        // clang-format off
        static unsigned char {name}[] = {{
        {hex_bytes}
        }};

        static unsigned int {name}_len = sizeof({name});
        // clang-format on
        """
    ).format(source=source.as_posix(), name=name, hex_bytes=hex_bytes)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("asm", type=Path, help="NASM source (.asm)")
    parser.add_argument(
        "-o",
        "--output",
        type=Path,
        help="Header path (default: <asm_dir>/<stem>_data.h)",
    )
    parser.add_argument(
        "-n",
        "--name",
        help="C array name (default: asm file stem)",
    )
    parser.add_argument(
        "--nasm",
        default="nasm",
        help="nasm executable (default: %(default)s)",
    )
    args = parser.parse_args()

    asm: Path = args.asm
    if not asm.is_file():
        print(f"error: asm not found: {asm}", file=sys.stderr)
        return 1

    name = args.name or asm.stem
    output: Path = args.output or asm.with_name(f"{asm.stem}_data.h")

    with tempfile.TemporaryDirectory(prefix="asm2c.") as tmp:
        bin_path = Path(tmp) / "asm2c.bin"
        try:
            subprocess.run(
                [args.nasm, "-f", "bin", "-o", str(bin_path), str(asm)],
                check=True,
            )
        except FileNotFoundError:
            print(f"error: nasm not found: {args.nasm}", file=sys.stderr)
            return 1
        except subprocess.CalledProcessError as exc:
            return exc.returncode

        data = bin_path.read_bytes()

    if not data:
        print("error: nasm produced empty binary", file=sys.stderr)
        return 1

    try:
        source_display = asm.resolve().relative_to(Path.cwd().resolve())
    except ValueError:
        source_display = asm

    output.write_text(
        bytes_to_c_array(data, name, source=source_display),
        encoding="utf-8",
    )
    print(f"wrote {output.name} ({len(data)} bytes)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
